package com.hrtbuddy;

import android.content.*; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;

final class BackupManager {
    static void clearLogs(Context c){android.content.SharedPreferences.Editor e=State.p(c).edit();for(String key:State.p(c).getAll().keySet())if(key.startsWith("done_")||key.startsWith("skip_")||key.startsWith("log_"))e.remove(key);e.apply();}
    static String csv(Context c){ StringBuilder out=new StringBuilder("HRT Buddy backup,1\nType,Name,Value,Date,Action\n"); android.content.SharedPreferences p=State.p(c); String[] keys={"cycle","anchorDay","anchor","progStart","progEnd","patchDays","patchTime","progTime","checkinTime","trackBleeding","trackPain","trackMood","trackOverall"}; for(String k:keys){Object value=p.getAll().get(k);row(out,"SETTING",k,value==null?"":String.valueOf(value),"","");} for(Map.Entry<String,?> e:p.getAll().entrySet()){String k=e.getKey();if(k.startsWith("cycle_len_")||k.startsWith("cycle_prev_"))row(out,"SETTING",k,String.valueOf(e.getValue()),"","");else if(k.startsWith("done_")||k.startsWith("skip_")){String action=k.startsWith("done_")?"done":"skip";String date=k.substring(5);Object value=e.getValue();if(value instanceof Set)for(Object item:(Set<?>)value)row(out,"LOG",String.valueOf(item),"",date,action);}else if(k.startsWith("log_")){String rest=k.substring(4);int marker=rest.indexOf('_');if(marker>0)row(out,"DAILY",rest.substring(marker+1),String.valueOf(e.getValue()),rest.substring(0,marker),"");}} return out.toString(); }
    static void row(StringBuilder out,String type,String name,String value,String date,String action){out.append(escape(type)).append(',').append(escape(name)).append(',').append(escape(value)).append(',').append(escape(date)).append(',').append(escape(action)).append('\n');}
    static String escape(String s){if(s==null)return "";return s.contains(",")||s.contains("\"")||s.contains("\n")?"\""+s.replace("\"","\"\"")+"\"":s;}
    static void importCsv(Context c,InputStream input)throws IOException{BufferedReader r=new BufferedReader(new InputStreamReader(input,StandardCharsets.UTF_8));String line;boolean header=false;Map<String,Set<String>> logs=new HashMap<>();android.content.SharedPreferences.Editor e=State.p(c).edit().clear();while((line=r.readLine())!=null){if(line.startsWith("Type,")){header=true;continue;}if(line.startsWith("CycleCue")||line.startsWith("HRT Buddy")||line.trim().isEmpty())continue;List<String> v=parse(line);if(v.size()<5)continue;if("SETTING".equals(v.get(0))){String k=v.get(1),value=v.get(2);if(value.isEmpty())continue;if("anchor".equals(k))e.putLong(k,Long.parseLong(value));else if("cycle".equals(k)||"anchorDay".equals(k)||"progStart".equals(k)||"progEnd".equals(k)||k.startsWith("cycle_len_"))e.putInt(k,Integer.parseInt(value));else if("trackBleeding".equals(k)||"trackPain".equals(k)||"trackMood".equals(k)||"trackOverall".equals(k))e.putBoolean(k,Boolean.parseBoolean(value));else e.putString(k,value);}else if("LOG".equals(v.get(0))){String key=("skip".equals(v.get(4))?"skip_":"done_")+v.get(3);logs.computeIfAbsent(key,k->new HashSet<>()).add(v.get(1));}else if("DAILY".equals(v.get(0))){String key="log_"+v.get(3)+"_"+v.get(1);if("pain".equals(v.get(1))||"mood".equals(v.get(1))||"overall".equals(v.get(1)))e.putInt(key,Integer.parseInt(v.get(2)));else e.putString(key,v.get(2));}}if(!header)throw new IOException("Not an HRT Buddy backup");for(Map.Entry<String,Set<String>> log:logs.entrySet())e.putStringSet(log.getKey(),log.getValue());e.apply();}
    static List<String> parse(String line){List<String> out=new ArrayList<>();StringBuilder s=new StringBuilder();boolean quoted=false;for(int i=0;i<line.length();i++){char ch=line.charAt(i);if(ch=='\"'){if(quoted&&i+1<line.length()&&line.charAt(i+1)=='\"'){s.append('"');i++;}else quoted=!quoted;}else if(ch==','&&!quoted){out.add(s.toString());s.setLength(0);}else s.append(ch);}out.add(s.toString());return out;}
}
